insert into offer_types (id, share, fee_pct, data) values
  ('click', false, 0, '{"t":"реклама с оплатой за переход","short":"переход","cta":"запустить рекламу","d":"Показываем ваш оффер в приложении билайна в нужный момент. Клиент нажимает и попадает к вам: на сайт, в Карты или звонит.","gets":"ваше предложение, когда оно нужно","pay":"за переход, показы бесплатно","fit":"кофейни, сервисы, магазины, клиники","rate":0,"unit":"визиты","many":"гостей","per":"один гость","payFor":"за клик","live":"сохранили купон","wait":"Гости ещё идут до вас. Визиты в точку появятся завтра к 18:00, пока смотрите, как люди реагируют на объявление.","fields":[],"via":{"label":"","options":[],"hint":""}}'::jsonb),
  ('coupon', true, 20, '{"t":"купон со скидкой","short":"купон","cta":"подключить купоны","d":"Клиент заранее покупает купон в приложении билайна, а потом приходит к вам и показывает его на кассе.","gets":"скидку по оплаченному купону","pay":"комиссию с погашенного купона","fit":"кафе, салоны красоты, развлечения","rate":0.03,"unit":"погашенные купоны","many":"купонов","per":"вам за купон","payFor":"комиссия с купона","live":"купили купон","wait":"Купоны покупают сразу, а погашать на кассе начнут завтра. Выплата за погашенные — 1 декабря.","fields":[{"k":"what","label":"что в купоне","wide":true},{"k":"price","label":"цена купона","num":true,"suffix":"₽"},{"k":"old","label":"обычная цена","num":true,"suffix":"₽"}],"via":{"label":"как гасить купон","options":["код в кабинете","приложение кассира","коннектор к кассе"],"hint":"кассир вводит код с телефона гостя, купон сгорает"}}'::jsonb),
  ('lead', false, 0, '{"t":"оплата за заявку","short":"заявка","cta":"подключить заявки","d":"Клиент оставляет заявку, регистрируется или ставит ваше приложение. Дальше вы работаете с ним сами.","gets":"продукт или услугу по заявке","pay":"фикс за подтверждённую заявку","fit":"банки, страхование, онлайн-школы","rate":0,"unit":"заявки","many":"заявок","per":"цена заявки","payFor":"за заявку","live":"оставили заявку","wait":"Заявки уже приходят. Отметьте, какие подтверждены, за 7 дней — после этого засчитаем сами.","fields":[{"k":"what","label":"на что заявка","wide":true},{"k":"price","label":"плачу за заявку","num":true,"suffix":"₽"}],"via":{"label":"куда отправлять заявки","options":["почта","Битрикс24","amoCRM","API"],"hint":"имя и телефон клиента, с его согласия"}}'::jsonb),
  ('promo', false, 0, '{"t":"промокод на покупку","short":"промокод","cta":"подключить промокод","d":"Клиент получает промокод и покупает на вашем сайте. За возвраты не платите.","gets":"скидку на вашем сайте","pay":"процент с оплаченной покупки","fit":"интернет-магазины, доставка, билеты","rate":0,"unit":"покупки","many":"покупок","per":"комиссия с покупки","payFor":"% с покупки","live":"скопировали промокод","wait":"Покупки по коду увидим после первой выгрузки заказов. Комиссию спишем через 14 дней, когда пройдёт срок возврата.","fields":[{"k":"code","label":"промокод"},{"k":"off","label":"скидка","num":true,"suffix":"%"},{"k":"fee","label":"комиссия билайну","num":true,"suffix":"%"},{"k":"check","label":"средний чек","num":true,"suffix":"₽"}],"via":{"label":"как передадите заказы","options":["файл раз в неделю","постбэк","коннектор 1С"],"hint":"нужны сумма заказа и возвраты, без данных клиента"}}'::jsonb),
  ('sub', true, 30, '{"t":"подписка на сервис","short":"подписка","cta":"подключить подписку","d":"Клиент подключает ваш сервис и платит каждый месяц со счёта телефона, пока подписка активна.","gets":"пробный период и оплату со счёта","pay":"долю каждого платежа","fit":"кино, музыка, облако, курсы","rate":0.008,"unit":"подписки","many":"подписок","per":"вам с подписки в месяц","payFor":"доля платежа","live":"начали пробный период","wait":"Идёт пробный период. Первые платные продления — через неделю, выплата раз в месяц.","fields":[{"k":"what","label":"что в подписке","wide":true},{"k":"price","label":"в месяц","num":true,"suffix":"₽"},{"k":"trial","label":"бесплатно","num":true,"suffix":"дн."}],"via":{"label":"как выдать доступ","options":["коды доступа","API"],"hint":"включаем и отключаем доступ при оплате и отмене"}}'::jsonb);
